  namespace(name: string): string {
    // Validate that the whole `--foo` variable is passed in.
    if (typeof ngDevMode === 'undefined' || ngDevMode) {
      if (!name.startsWith('--')) {
        throw new Error(
          `CSS variable names passed to \`CssVarNamespacer\` must start with '--', got: '${name}'`,
        );
