  <header>
    <h1>Tower of Hanoi</h1>
    <p class="subtitle">Move all disks to the rightmost peg. You can only place a smaller disk on a larger one.</p>
  </header>

  <div class="controls">
    <div class="control-group">
      <label>Disks</label>
      <div class="disk-buttons">
        @for (n of [3, 4, 5, 6, 7]; track n) {
          <button
            class="disk-btn"
            [class.active]="diskCount() === n"
            (click)="setDiskCount(n)"
          >{{ n }}</button>
        }
      </div>
    </div>

    <div class="stats">
      <div class="stat">
        <span class="stat-label">Moves</span>
        <span class="stat-value">{{ moves() }}</span>
      </div>
      <div class="stat">
        <span class="stat-label">Optimal</span>
        <span class="stat-value">{{ minMoves() }}</span>
      </div>
    </div>

    <button class="reset-btn" (click)="initGame()">↺ Reset</button>
  </div>

  @if (won()) {
    <div class="win-banner">
      🎉 Solved in {{ moves() }} moves!
      @if (moves() === minMoves()) {
        <span class="perfect">Perfect score!</span>
      }
    </div>
  }

  <div class="game-area">
    @for (peg of pegs(); track trackByIndex($index)) {
      <div
        class="peg-column"
        [class.selected]="selected() === $index"
        (click)="selectPeg($index)"
        [attr.aria-label]="'Peg ' + ($index + 1)"
        role="button"
        [attr.tabindex]="0"
        (keydown.enter)="selectPeg($index)"
        (keydown.space)="selectPeg($index)"
      >
        <div class="peg-label">{{ ['A', 'B', 'C'][$index] }}</div>

        <div class="peg-area">
          <div class="peg-rod"></div>
          <div class="peg-base"></div>

          <div class="disks-stack">
            @for (disk of peg; track disk) {
              <div
                class="disk"
                [style.width.%]="diskWidth(disk)"
                [style.background-color]="diskColor(disk)"
                [attr.aria-label]="'Disk ' + disk"
              >
                <span class="disk-label">{{ disk }}</span>
              </div>
            }
          </div>
        </div>

        @if (selected() === $index) {
          <div class="selection-indicator">✦ selected</div>
        }
      </div>
    }
  </div>

  <p class="hint">
